# Test all variations of 3x3 with exactly one 8, one 7, seven 4s
# 8 can be in 9 positions, 7 can be in remaining 8 positions → 9*8=72 combinations

from itertools import permutations

def check_pattern(grid):
    fl = [v for row in grid for v in row]
    if fl.count(8) == 1 and fl.count(7) == 1 and fl.count(4) == 7:
        return True
    return False

base = [[4, 4, 4], [4, 4, 4], [4, 4, 4]]
# Generate all valid patterns
valid_patterns = []

# Try all positions for 8 and 7
for r8 in range(3):
    for c8 in range(3):
        for r7 in range(3):
            for c7 in range(3):
                if (r8, c8) == (r7, c7):
                    continue
                grid = [[4]*3 for _ in range(3)]
                grid[r8][c8] = 8
                grid[r7][c7] = 7
                if check_pattern(grid):
                    valid_patterns.append((grid, (r8, c8, r7, c7)))

print(f"Found {len(valid_patterns)} valid patterns (one 8, one 7, seven 4s)")

